  def test_lookup_transfers_round_trips_all_fields
    transfer_id = TigerBeetle.id
    debit_account_id = TigerBeetle.id
    credit_account_id = TigerBeetle.id
    user_data_128 = TigerBeetle.id
    @client.create_accounts(
      [
        TigerBeetle::Account.new(
          id: debit_account_id,
          ledger: 1,
          code: 1
        ),
        TigerBeetle::Account.new(
          id: credit_account_id,
          ledger: 1,
          code: 1
        )
      ]
    )
    @client.create_transfers(
      [
        TigerBeetle::Transfer.new(
          id: transfer_id,
          debit_account_id: debit_account_id,
          credit_account_id: credit_account_id,
          amount: 99,
          ledger: 1,
          code: 7,
          user_data_128: user_data_128,
          user_data_64: 8888888888,
          user_data_32: 54321
        )
      ]
    )
    transfers = @client.lookup_transfers([transfer_id])
    assert_equal(1, transfers.length)
    assert_equal(transfer_id, transfers[0].id)
    assert_equal(debit_account_id, transfers[0].debit_account_id)
    assert_equal(credit_account_id, transfers[0].credit_account_id)
    assert_equal(99, transfers[0].amount)
    assert_equal(1, transfers[0].ledger)
    assert_equal(7, transfers[0].code)
    assert_equal(user_data_128, transfers[0].user_data_128)
    assert_equal(8888888888, transfers[0].user_data_64)
    assert_equal(54321, transfers[0].user_data_32)
    transfer = transfers[0]
    assert_operator(transfer.timestamp, :>, 0)
  end

